  "implementation": "def solve(case):
    # Validate required top-level keys
    required_keys = ('initial_state', 'max_steps', 'tool_observations', 'transitions')
    for key in required_keys:
        if key not in case:
            raise ValueError(f'Missing required field: {key}')

    initial_state = case['initial_state']
    max_steps = case['max_steps']
    tool_observations = case['tool_observations']
    transitions = case['transitions']

    # Validate types and values
    if not isinstance(max_steps, int) or max_steps < 0:
        raise ValueError('max_steps must be a non-negative integer')
    if not isinstance(tool_observations, dict):
        raise ValueError('tool_observations must be a dict')
    if not isinstance(transitions, dict):
        raise ValueError('transitions must be a dict')
    for tool, obs in tool_observations.items():
        if not isinstance(tool, str) or not isinstance(obs, str):
            raise ValueError('tool_observations keys and values must be strings')

    # Validate that initial_state exists in transitions
    if initial_state not in transitions:
        raise ValueError(f'initial_state {initial_state!r} not found in transitions')

    # Validate all states referenced in transitions are defined and structurally complete
    for state_name, state_def in transitions.items():
        if not isinstance(state_def, dict) or 'kind' not in state_def:
            raise ValueError(f'State {state_name!r} must be a dict with a "kind" field')
        kind = state_def['kind']
        if kind == 'action':
            for field in ('action', 'next_by_observation', 'default_next'):
                if field not in state_def:
                    raise ValueError(f'Action state {state_name!r} missing field {field!r}')
            if not isinstance(state_def['action'], str):
                raise ValueError(f'Action in state {state_name!r} must be a string')
            if not isinstance(state_def['next_by_observation'], dict):
                raise ValueError(f'next_by_observation in state {state_name!r} must be a dict')
            for obs, next_state in state_def['next_by_observation'].items():
                if not isinstance(obs, str) or not isinstance(next_state, str):
                    raise ValueError(f'next_by_observation entries in state {state_name!r} must be string pairs')
                if next_state not in transitions:
                    raise ValueError(f'State {state_name!r} next_by_observation points to undefined state {next_state!r}')
            default_next = state_def['default_next']
            if not isinstance(default_next, str):
                raise ValueError(f'default_next in state {state_name!r} must be a string')
            if default_next not in transitions:
                raise ValueError(f'State {state_name!r} default_next points to undefined state {default_next!r}')
        elif kind == 'final':
            if 'value' not in state_def:
                raise ValueError(f'Final state {state_name!r} missing field "value"')
            if state_def['value'] is not None and not isinstance(state_def['value'], str):
                raise ValueError(f'Final state {state_name!r} value must be a string or null')
        else:
            raise ValueError(f'State {state_name!r} has unknown kind {kind!r}')

    # Simulation
    state = initial_state
    step = 0
    trace = []
    status = None
    final = None

    while step < max_steps:
        if state not in transitions:
            # Should not happen due to validation, but guard
            raise ValueError(f'State {state!r} not found in transitions during execution')
        state_def = transitions[state]
        if state_def['kind'] == 'final':
            status = 'completed'
            final = state_def['value']
            break
        # It's an action state
        action = state_def['action']
        # Determine observation
        if action in tool_observations:
            observation = tool_observations[action]
        else:
            observation = 'invalid_action'  # invalid-action feedback
        step += 1
        # Determine next state
        if observation in state_def['next_by_observation']:
            next_state = state_def['next_by_observation'][observation]
        else:
            next_state = state_def['default_next']
        trace.append({
            'step': step,
            'action': action,
            'observation': observation,
            'state': state
        })
        state = next_state
        # Check if we reached final state after transition (in case final state is reached via action)
        if state in transitions and transitions[state]['kind'] == 'final':
            status = 'completed'
            final = transitions[state]['value']
            break

    if status is None:
        # Exited due to max steps without reaching final state
        status = 'failed'
        final = None

    return {
        'final': final,
        'status': status,
        'trace': trace
    }
